import { prisma } from "@/src/lib/prisma";
import { getServerSession } from "next-auth";
import Link from "next/link";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/Card";

export default async function DashboardPage() {
  const session = await getServerSession();
  
  // Data ophalen uit de database
  const taskCount = await prisma.task.count();
  const todoCount = await prisma.task.count({ where: { status: "TODO" } });

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      <header>
        <h1 className="text-4xl font-extrabold text-transparent bg-clip-text bg-gradient-to-r from-teal-300 to-fuchsia-400">
          Welkom terug, {session?.user?.email?.split('@')[0] || 'Gebruiker'}! 👋
        </h1>
        <p className="text-teal-200/60 mt-2">Hier is de status van je huidige projecten in Sprint 1.</p>
      </header>

      {/* Stat Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="Totaal Taken" value={taskCount.toString()} color="teal" />
        <StatCard title="Openstaand" value={todoCount.toString()} color="fuchsia" />
        <StatCard title="Voltooid" value="0" color="green" />
        <StatCard title="Actieve Sprint" value="S1" color="blue" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Voortgangsgrafiek Sectie (Sprint 4 Voorbereiding) */}
        <Card className="lg:col-span-2 bg-[#0E153A]/60 border-teal-400/20 backdrop-blur-md">
          <CardHeader>
            <CardTitle className="text-teal-300 text-lg uppercase tracking-widest">Project Voortgang (US-12)</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="h-64 flex flex-col items-center justify-center border-2 border-dashed border-teal-400/10 rounded-2xl bg-[#070B24]/40">
              <div className="text-teal-400/20 text-5xl mb-4">📊</div>
              <p className="text-teal-200/40 font-medium">Grafieken worden geladen in Sprint 4...</p>
              <div className="mt-4 w-48 h-2 bg-teal-400/10 rounded-full overflow-hidden">
                <div className="w-1/3 h-full bg-gradient-to-r from-teal-400 to-fuchsia-400" />
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Snelle Acties */}
        <Card className="bg-[#0E153A]/60 border-teal-400/20 backdrop-blur-md">
          <CardHeader>
            <CardTitle className="text-teal-300 text-lg uppercase tracking-widest">Snelle Acties</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <Link href="/tasks" className="flex items-center justify-center w-full bg-gradient-to-r from-teal-400 to-fuchsia-400 text-black font-bold p-3 rounded-xl hover:scale-[1.03] transition-all shadow-[0_0_20px_rgba(45,212,191,0.3)]">
              + Nieuwe Taak
            </Link>
            <Link href="/scrumboard" className="flex items-center justify-center w-full border border-teal-400/30 text-teal-100 p-3 rounded-xl hover:bg-teal-400/10 transition-all">
              Bekijk Scrumboard
            </Link>
          </CardContent>
        </Card>
      </div>

      {/* Recente Activiteiten */}
      <Card className="bg-[#0E153A]/60 border-teal-400/20 shadow-2xl">
        <CardHeader className="border-b border-teal-400/10">
          <CardTitle className="text-teal-300 text-lg uppercase tracking-widest">Recente Taken</CardTitle>
        </CardHeader>
        <CardContent className="pt-6">
          <div className="text-center py-8 text-teal-200/30 italic">
            Geen recente activiteiten gevonden. Begin met het toevoegen van taken!
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

function StatCard({ title, value, color }: { title: string; value: string; color: string }) {
  const colors: any = {
    teal: "from-teal-500/20",
    fuchsia: "from-fuchsia-500/20",
    green: "from-green-500/20",
    blue: "from-blue-500/20",
  };

  return (
    <div className={`bg-[#0E153A]/60 border border-teal-400/20 p-6 rounded-2xl bg-gradient-to-br ${colors[color]} to-transparent shadow-lg hover:border-teal-400/40 transition-all group`}>
      <p className="text-teal-400/60 text-xs font-bold uppercase tracking-widest">{title}</p>
      <h2 className="text-3xl font-black mt-2 text-white group-hover:scale-105 transition-transform origin-left">{value}</h2>
    </div>
  );
}